  status,
  testId,
  label,
}: {
  status: ChainStatus | null;
  testId: string;
  label: string;
}) {
  if (status === null) return null;
  if (status.state === "valid") {
    return (
      <Badge
        data-testid={testId}
        className="border-verdict-accept/35 bg-verdict-accept/10 text-verdict-accept"
      >
        {label} valid · {status.count} events
      </Badge>
    );
  }
  return (
    <Badge variant="destructive" data-testid={testId}>
      {status.state === "broken" ? `${label} broken at seq ${status.brokenAtSeq}` : "Verification failed"}
    </Badge>
  );
}

